-- HQ private PostgreSQL schema. Run with a migration credential, not the app role.
CREATE SCHEMA IF NOT EXISTS hq;
REVOKE ALL ON SCHEMA hq FROM PUBLIC;
SET LOCAL search_path TO hq;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,department TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(token TEXT PRIMARY KEY,email TEXT NOT NULL,role TEXT NOT NULL,department TEXT NOT NULL,expires DOUBLE PRECISION NOT NULL,used INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,department TEXT NOT NULL,owner TEXT REFERENCES users(id),status TEXT NOT NULL,priority TEXT NOT NULL,due TEXT NOT NULL,created TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'General task');
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,title TEXT NOT NULL,department TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL,feedback TEXT NOT NULL DEFAULT '',created TEXT NOT NULL, author TEXT, reviewer TEXT);
CREATE TABLE IF NOT EXISTS announcements(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,department TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT,action TEXT,target TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER,until DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS affiliate_policy(id INTEGER PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),permission TEXT NOT NULL,scope_type TEXT NOT NULL,scope_id TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_comments(id TEXT PRIMARY KEY,task_id TEXT REFERENCES tasks(id),author TEXT REFERENCES users(id),body TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,sender TEXT NOT NULL REFERENCES users(id),recipient TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created TEXT NOT NULL,read_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,resource TEXT NOT NULL,record_id TEXT NOT NULL,created TEXT NOT NULL,read_at TEXT);
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY,title TEXT NOT NULL,department TEXT NOT NULL,organizer TEXT REFERENCES users(id),starts TEXT NOT NULL,ends TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL,notes TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meeting_members(meeting_id TEXT REFERENCES meetings(id),user_id TEXT REFERENCES users(id),PRIMARY KEY(meeting_id,user_id));
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,title TEXT NOT NULL,department TEXT NOT NULL,owner TEXT REFERENCES users(id),body TEXT NOT NULL,url TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS affiliates(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,program TEXT NOT NULL,owner TEXT REFERENCES users(id),status TEXT NOT NULL,training INTEGER NOT NULL DEFAULT 0,founding_number INTEGER UNIQUE,founding_until TEXT,code TEXT UNIQUE NOT NULL,created TEXT NOT NULL, approved_on TEXT);
CREATE TABLE IF NOT EXISTS affiliate_sales(id TEXT PRIMARY KEY,affiliate_id TEXT REFERENCES affiliates(id),invoice TEXT UNIQUE NOT NULL,customer TEXT NOT NULL,product TEXT NOT NULL,net_cents INTEGER NOT NULL,rate_bps INTEGER NOT NULL,commission_cents INTEGER NOT NULL,status TEXT NOT NULL,clear_on TEXT NOT NULL,evidence TEXT NOT NULL,payout_ref TEXT NOT NULL DEFAULT '',created TEXT NOT NULL, months INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subscription_commission_terms(affiliate_id TEXT REFERENCES affiliates(id),customer TEXT NOT NULL,rate_bps INTEGER NOT NULL,PRIMARY KEY(affiliate_id,customer));
CREATE INDEX IF NOT EXISTS grants_user ON grants(user_id);
CREATE INDEX IF NOT EXISTS message_inbox ON messages(recipient,read_at);
CREATE INDEX IF NOT EXISTS notification_inbox ON notifications(user_id,read_at);
CREATE TABLE IF NOT EXISTS partner_accounts(id TEXT PRIMARY KEY REFERENCES affiliates(id),password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS partner_sessions(token TEXT PRIMARY KEY,partner_id TEXT REFERENCES affiliates(id),csrf TEXT,expires DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,user_id TEXT,session_token TEXT,expires DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS integration_events(source TEXT,event_id TEXT,payload_hash TEXT,created TEXT,PRIMARY KEY(source,event_id));
CREATE TABLE IF NOT EXISTS division_records(id TEXT PRIMARY KEY,department TEXT,kind TEXT,external_id TEXT,data TEXT,created TEXT,UNIQUE(department,kind,external_id));
CREATE TABLE IF NOT EXISTS commerce_orders(id TEXT PRIMARY KEY,email TEXT,product TEXT,net_cents INTEGER,currency TEXT,affiliate_id TEXT REFERENCES affiliates(id),status TEXT,provider_id TEXT UNIQUE,created TEXT, payment_intent TEXT);
CREATE TABLE IF NOT EXISTS schema_version(id INTEGER PRIMARY KEY,version INTEGER NOT NULL);
INSERT INTO schema_version VALUES(1,1) ON CONFLICT DO NOTHING;
INSERT INTO affiliate_policy VALUES(1,'{"rates": {"Business": [1000, 1500, 2000], "Academy": [1500, 2000, 2500], "Studio": [800, 1000, 1200]}, "founding_rates": {"Business": 2000, "Academy": 2500, "Studio": 1200}}') ON CONFLICT DO NOTHING;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;
ALTER TABLE tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE announcements ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE affiliate_policy ENABLE ROW LEVEL SECURITY;
ALTER TABLE grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE task_comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE meetings ENABLE ROW LEVEL SECURITY;
ALTER TABLE meeting_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE resources ENABLE ROW LEVEL SECURITY;
ALTER TABLE affiliates ENABLE ROW LEVEL SECURITY;
ALTER TABLE affiliate_sales ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscription_commission_terms ENABLE ROW LEVEL SECURITY;
ALTER TABLE partner_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE partner_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth_states ENABLE ROW LEVEL SECURITY;
ALTER TABLE integration_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE division_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE commerce_orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE schema_version ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA hq FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA hq FROM PUBLIC;
CREATE TABLE IF NOT EXISTS service_tokens(name TEXT PRIMARY KEY,encrypted TEXT NOT NULL);
ALTER TABLE service_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON service_tokens FROM PUBLIC;

ALTER TABLE partner_accounts ADD COLUMN IF NOT EXISTS verified INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS account_tokens(token TEXT PRIMARY KEY,kind TEXT,account_id TEXT,expires DOUBLE PRECISION,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS mail_outbox(id TEXT PRIMARY KEY,recipient TEXT,encrypted TEXT,attempts INTEGER NOT NULL DEFAULT 0,next_at DOUBLE PRECISION,sent TEXT,created TEXT);
ALTER TABLE account_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE mail_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON account_tokens,mail_outbox FROM PUBLIC;
